<?php
require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('examiner');$q=db()->prepare('SELECT p.*,pe.status assignment_status,pe.evaluation_due_at FROM projects p JOIN project_examiners pe ON pe.project_id=p.id WHERE pe.examiner_id=? AND pe.status<>"withdrawn" ORDER BY pe.evaluation_due_at');$q->execute([$u['id']]);$rows=$q->fetchAll();$pageTitle='Assigned projects';require dirname(__DIR__).'/includes/header.php';
?><p class="page-intro">Only projects assigned to your examiner account are shown.</p><div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Reference</th><th>Project</th><th>Assignment</th><th>Due</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['reference_no']) ?></td><td><?= e($r['title']) ?></td><td><?= status_badge($r['assignment_status']) ?></td><td><?= e($r['evaluation_due_at']??'—') ?></td><td><a class="btn btn-sm btn-primary" href="<?= e(url('examiner/evaluations.php?project_id='.(int)$r['id'])) ?>">Evaluate</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5"><div class="empty-state">No projects have been assigned to your examiner account yet. Assigned evaluations will appear here.</div></td></tr><?php endif; ?></tbody></table></div></div><?php require dirname(__DIR__).'/includes/footer.php'; ?>
